import itertools
import json

def solve():
    houses = [1, 2, 3]

    Names = ['Eric', 'Peter', 'Arnold']
    smoothies = ['cherry', 'watermelon', 'desert']
    flowers = ['carnations', 'lilies', 'daffodils']
    animals = ['cat', 'horse', 'bird']
    hobbies = ['photography', 'cooking', 'gardening']

    # Utility: index positions are 1-based in constraints
    def pos_of(item_list, value):
        return item_list.index(value) + 1

    solution = None

    for name_at in itertools.permutations(Names):
        # Clue 5 implies Peter is not in house 1
        if pos_of(name_at, 'Peter') == 1:
            continue

        for hobby_at in itertools.permutations(hobbies):
            # Clue 8: The photography enthusiast is Eric.
            if pos_of(hobby_at, 'photography') != pos_of(name_at, 'Eric'):
                continue

            # Clue 5: The person who loves cooking is directly left of Peter.
            if pos_of(hobby_at, 'cooking') + 1 != pos_of(name_at, 'Peter'):
                continue

            for animal_at in itertools.permutations(animals):
                # Clue 1: The person who keeps horses and the photography enthusiast are next to each other.
                if abs(pos_of(animal_at, 'horse') - pos_of(hobby_at, 'photography')) != 1:
                    continue

                for smoothie_at in itertools.permutations(smoothies):
                    # Clue 2: The bird keeper is the person who likes Cherry smoothies.
                    if pos_of(animal_at, 'bird') != pos_of(smoothie_at, 'cherry'):
                        continue

                    # Clue 3: The person who loves cooking is the Desert smoothie lover.
                    if pos_of(hobby_at, 'cooking') != pos_of(smoothie_at, 'desert'):
                        continue

                    # Clue 7: The Watermelon smoothie lover is the person who keeps horses.
                    if pos_of(smoothie_at, 'watermelon') != pos_of(animal_at, 'horse'):
                        continue

                    for flower_at in itertools.permutations(flowers):
                        # Clue 4: The person who enjoys gardening is the person who loves a carnations arrangement.
                        if pos_of(hobby_at, 'gardening') != pos_of(flower_at, 'carnations'):
                            continue

                        # Clue 6: The person who loves a bouquet of daffodils is the Desert smoothie lover.
                        if pos_of(flower_at, 'daffodils') != pos_of(smoothie_at, 'desert'):
                            continue

                        # All constraints satisfied; construct solution
                        rows = []
                        for i in range(3):
                            house_num = str(i + 1)
                            rows.append([
                                house_num,
                                name_at[i],
                                smoothie_at[i],
                                flower_at[i],
                                animal_at[i],
                                hobby_at[i]
                            ])
                        solution = {
                            "solution": {
                                "header": ["House", "Name", "smoothie", "flower", "animal", "hobby"],
                                "rows": rows
                            }
                        }
                        return solution
    return None

def main():
    result = solve()
    if result is None:
        print(json.dumps({"error": "No solution found"}))
    else:
        print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()
